SELECT count(*) AS deals_total, count(*) FILTER (WHERE status <> 'Аннулирован(Не оплачен)') AS deals_not_cancelled
FROM v_deals
WHERE deal_date >= DATE '2023-01-01' AND deal_date < DATE '2024-01-01';

SELECT deal_no, contract_no, seller_name, seller_broker, seller_broker_name, status, deal_date
FROM v_deals
WHERE deal_no = 100001;
